import { useEffect, useState } from "react";
import * as Clipboard from "expo-clipboard";
import {
  ActivityIndicator,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from "react-native";
import QRCode from "react-native-qrcode-svg";
import { ApiClient, ApiError } from "./api";
import { depositQrValue } from "./qr";
import type { Asset, DepositAddress } from "./types";
import type { ConnectionState } from "./privateSocket";

interface DepositScreenProps {
  api: ApiClient;
  token: string;
  connectionState: ConnectionState;
  onLogout: () => Promise<void>;
  copy?: (value: string) => Promise<unknown>;
}

const CONNECTION_LABEL: Record<ConnectionState, string> = {
  connecting: "Conectando",
  live: "En vivo",
  reconnecting: "Reconectando",
  disconnected: "Desconectado",
};

export function DepositScreen({
  api,
  token,
  connectionState,
  onLogout,
  copy = Clipboard.setStringAsync,
}: DepositScreenProps) {
  const [asset, setAsset] = useState<Asset>("ETH");
  const [deposit, setDeposit] = useState<DepositAddress | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [requestVersion, setRequestVersion] = useState(0);
  const [copied, setCopied] = useState(false);
  const [loggingOut, setLoggingOut] = useState(false);

  useEffect(() => {
    const controller = new AbortController();
    let active = true;
    setLoading(true);
    setDeposit(null);
    setError(null);
    setCopied(false);
    void api.depositAddress(asset, token, controller.signal).then(
      (response) => {
        if (!active) return;
        setDeposit(response);
        setLoading(false);
      },
      (cause: unknown) => {
        if (!active || (cause instanceof Error && cause.name === "AbortError")) return;
        if (!(cause instanceof ApiError && cause.code === "UNAUTHENTICATED")) {
          setError("No pudimos obtener la dirección. Revisá tu conexión e intentá nuevamente.");
        }
        setLoading(false);
      },
    );
    return () => {
      active = false;
      controller.abort();
    };
  }, [api, asset, token, requestVersion]);

  async function copyAddress() {
    if (!deposit) return;
    try {
      await copy(deposit.address);
      setCopied(true);
    } catch {
      setError("No pudimos copiar la dirección. Mantenela presionada para seleccionarla.");
    }
  }

  async function logout() {
    if (loggingOut) return;
    setLoggingOut(true);
    await onLogout();
  }

  const qrValue = deposit ? depositQrValue(deposit) : null;

  return (
    <ScrollView contentContainerStyle={styles.shell} keyboardShouldPersistTaps="handled">
      <View style={styles.topbar}>
        <View style={styles.brand}>
          <Text style={styles.mark}>O</Text>
          <Text style={styles.brandName}>ORBE</Text>
        </View>
        <Pressable accessibilityRole="button" disabled={loggingOut} onPress={() => void logout()}>
          <Text style={styles.logout}>{loggingOut ? "Cerrando…" : "Cerrar sesión"}</Text>
        </Pressable>
      </View>

      <View style={styles.heading}>
        <Text style={styles.eyebrow}>FONDOS · SEPOLIA</Text>
        <Text style={styles.title}>Depositar</Text>
        <Text style={styles.subtitle}>Elegí el activo y enviá únicamente por la red Sepolia.</Text>
      </View>

      <View accessibilityRole="tablist" style={styles.tabs}>
        {(["ETH", "USDC"] as const).map((candidate) => (
          <Pressable
            accessibilityRole="tab"
            accessibilityState={{ selected: asset === candidate }}
            key={candidate}
            onPress={() => setAsset(candidate)}
            style={[styles.tab, asset === candidate && styles.tabActive]}
          >
            <Text style={[styles.tabText, asset === candidate && styles.tabTextActive]}>
              {candidate === "USDC" ? "USDC-mock" : candidate}
            </Text>
          </Pressable>
        ))}
      </View>

      <View style={styles.card}>
        <View style={styles.metaRow}>
          <View>
            <Text style={styles.metaLabel}>RED</Text>
            <Text style={styles.metaValue}>Sepolia</Text>
          </View>
          <View style={styles.metaRight}>
            <Text style={styles.metaLabel}>CHAIN ID</Text>
            <Text style={styles.metaValue}>11155111</Text>
          </View>
        </View>

        {loading ? (
          <View style={styles.loading}>
            <ActivityIndicator color="#b7f397" size="large" />
            <Text style={styles.muted}>Obteniendo tu dirección…</Text>
          </View>
        ) : null}

        {error ? (
          <View style={styles.loading}>
            <Text accessibilityRole="alert" style={styles.error}>{error}</Text>
            <Pressable accessibilityRole="button" onPress={() => setRequestVersion((value) => value + 1)} style={styles.secondaryButton}>
              <Text style={styles.secondaryButtonText}>Reintentar</Text>
            </Pressable>
          </View>
        ) : null}

        {deposit && qrValue ? (
          <View style={styles.depositContent}>
            <View
              accessibilityLabel={`Código QR de depósito ${asset}: ${qrValue}`}
              style={styles.qrFrame}
              testID="deposit-qr"
            >
              <QRCode backgroundColor="#ffffff" color="#07110e" size={190} value={qrValue} />
            </View>
            <Text style={styles.assetTitle}>Dirección para {asset === "USDC" ? "USDC-mock" : "ETH"}</Text>
            <Text selectable style={styles.address} testID="deposit-address">{deposit.address}</Text>
            <Pressable accessibilityRole="button" onPress={() => void copyAddress()} style={styles.copyButton}>
              <Text style={styles.copyButtonText}>{copied ? "Dirección copiada ✓" : "Copiar dirección"}</Text>
            </Pressable>
            <Text style={styles.warning}>
              {asset === "ETH"
                ? "Enviá sólo ETH nativo por Sepolia."
                : "Enviá sólo el USDC-mock configurado por Sepolia. La dirección de recepción es la EOA mostrada arriba."}
            </Text>
          </View>
        ) : null}
      </View>

      <View style={styles.connection}>
        <View style={[styles.dot, connectionState === "live" && styles.dotLive]} />
        <Text style={styles.connectionText}>Canal privado: {CONNECTION_LABEL[connectionState]}</Text>
      </View>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
