  card: { backgroundColor: "#10221b", borderColor: "#203c31", borderWidth: 1, borderRadius: 24, padding: 20, minHeight: 450 },
  metaRow: { flexDirection: "row", justifyContent: "space-between", paddingBottom: 18, borderBottomColor: "#203b31", borderBottomWidth: 1 },
  metaRight: { alignItems: "flex-end" },
  metaLabel: { color: "#668779", fontSize: 10, letterSpacing: 1.5, fontWeight: "700" },
  metaValue: { color: "#dcece4", marginTop: 4, fontWeight: "600" },
  loading: { flex: 1, minHeight: 330, alignItems: "center", justifyContent: "center", gap: 16 },
