  error: { color: "#ffaaa3", textAlign: "center", lineHeight: 20 },
  secondaryButton: { borderColor: "#759b89", borderWidth: 1, borderRadius: 10, paddingHorizontal: 20, paddingVertical: 10 },
  secondaryButtonText: { color: "#c6ded2", fontWeight: "700" },
