import { SessionManager } from "./session";
import type { SessionStore } from "./sessionStore";

function fakeStore(overrides: Partial<SessionStore> = {}): jest.Mocked<SessionStore> {
  return {
    readToken: jest.fn().mockResolvedValue(null),
    saveToken: jest.fn().mockResolvedValue(undefined),
    clearToken: jest.fn().mockResolvedValue(undefined),
    ...overrides,
  } as jest.Mocked<SessionStore>;
}

describe("sesión segura", () => {
  test("AT-11-01-01 persiste únicamente el token y lo mantiene en memoria", async () => {
    const store = fakeStore();
    const manager = new SessionManager(store, jest.fn());
    await manager.establish("token-secreto");
    expect(store.saveToken).toHaveBeenCalledWith("token-secreto");
