    expect(manager.currentToken()).toBe("persistido");
  });

  test("AT-11-01-03 restaura ausencia de token", async () => {
    const manager = new SessionManager(fakeStore(), jest.fn());
    await expect(manager.restore()).resolves.toEqual({ token: null, readFailed: false });
  });

  test("AT-11-01-13 sanea un fallo de lectura sin propagar detalles", async () => {
    const store = fakeStore({ readToken: jest.fn().mockRejectedValue(new Error("detalle sensible")) });
    const manager = new SessionManager(store, jest.fn());
    await expect(manager.restore()).resolves.toEqual({ token: null, readFailed: true });
  });

