import { fireEvent, render, waitFor } from "@testing-library/react-native";
import { LoginScreen } from "./LoginScreen";
import { ApiError, NetworkError, type ApiClient } from "./api";

function client(login: jest.Mock): ApiClient {
  return { login } as unknown as ApiClient;
}

describe("HU-11-01 pantalla de login", () => {
  test("AT-11-01-01 envía credenciales y entra sólo después de persistir", async () => {
    const login = jest.fn().mockResolvedValue({ token: "token-opaco", expiresAt: "2030-01-01T00:00:00.000Z" });
    const authenticated = jest.fn().mockResolvedValue(undefined);
    const screen = render(<LoginScreen api={client(login)} onAuthenticated={authenticated} />);
    fireEvent.changeText(screen.getByLabelText("Email"), " trader@example.com ");
    fireEvent.changeText(screen.getByLabelText("Contraseña"), "Sup3rSecreta");
    fireEvent.press(screen.getByRole("button", { name: "Ingresar" }));
    await waitFor(() => expect(authenticated).toHaveBeenCalledWith("token-opaco"));
    expect(login).toHaveBeenCalledWith(" trader@example.com ", "Sup3rSecreta");
  });

  test("AT-11-01-04 usa un mensaje no enumerable para credenciales inválidas", async () => {
    const login = jest.fn().mockRejectedValue(new ApiError("INVALID_CREDENTIALS", "backend"));
    const screen = render(<LoginScreen api={client(login)} onAuthenticated={jest.fn()} />);
    fireEvent.changeText(screen.getByLabelText("Email"), "nobody@example.com");
    fireEvent.changeText(screen.getByLabelText("Contraseña"), "incorrecta");
    fireEvent.press(screen.getByRole("button", { name: "Ingresar" }));
    expect(await screen.findByText("Email o contraseña incorrectos.")).toBeTruthy();
  });

  test("AT-11-01-07 valida campos localmente sin llamar al backend", async () => {
    const login = jest.fn();
    const screen = render(<LoginScreen api={client(login)} onAuthenticated={jest.fn()} />);
    fireEvent.changeText(screen.getByLabelText("Email"), "no-es-email");
    fireEvent(screen.getByLabelText("Email"), "blur");
    fireEvent(screen.getByLabelText("Contraseña"), "blur");
    expect(await screen.findByText("Ingresá un email válido.")).toBeTruthy();
    expect(screen.getByText("Ingresá tu contraseña.")).toBeTruthy();
    expect(screen.getByRole("button", { name: "Ingresar" })).toBeDisabled();
    expect(login).not.toHaveBeenCalled();
  });

  test("AT-11-01-09 diferencia red caída y permite reintentar", async () => {
    const login = jest.fn()
      .mockRejectedValueOnce(new NetworkError())
      .mockResolvedValueOnce({ token: "nuevo", expiresAt: "2030-01-01T00:00:00.000Z" });
    const authenticated = jest.fn().mockResolvedValue(undefined);
    const screen = render(<LoginScreen api={client(login)} onAuthenticated={authenticated} />);
    fireEvent.changeText(screen.getByLabelText("Email"), "trader@example.com");
    fireEvent.changeText(screen.getByLabelText("Contraseña"), "correcta");
    fireEvent.press(screen.getByRole("button", { name: "Ingresar" }));
    expect(await screen.findByText(/No se pudo conectar/)).toBeTruthy();
    fireEvent.press(screen.getByRole("button", { name: "Ingresar" }));
    await waitFor(() => expect(authenticated).toHaveBeenCalledWith("nuevo"));
  });

  test("paridad AT-10-01-05 muestra VALIDATION_ERROR junto a cada campo", async () => {
    const login = jest.fn().mockRejectedValue(new ApiError(
      "VALIDATION_ERROR",
      "payload inválido",
      {
        issues: [
          { field: "email", message: "El email no tiene un formato válido." },
          { path: ["password"], message: "La contraseña no cumple el esquema." },
        ],
      },
      422,
    ));
    const screen = render(<LoginScreen api={client(login)} onAuthenticated={jest.fn()} />);
    fireEvent.changeText(screen.getByLabelText("Email"), "trader@example.com");
    fireEvent.changeText(screen.getByLabelText("Contraseña"), "secreta");
    fireEvent.press(screen.getByRole("button", { name: "Ingresar" }));

    expect(await screen.findByText("El email no tiene un formato válido.")).toBeTruthy();
    expect(screen.getByText("La contraseña no cumple el esquema.")).toBeTruthy();
  });

