    expect(screen.queryByText(/Keychain item inaccessible/)).toBeNull();
    await act(async () => { appStateListener?.("active"); });
    expect(await screen.findByText("Depositar")).toBeTruthy();
    expect(read).toHaveBeenCalledTimes(2);
    screen.unmount();
    listenerSpy.mockRestore();
  });

  test("AT-11-01-10 protege la vista al ir a background y la restaura al volver", async () => {
    let appStateListener: ((state: AppStateStatus) => void) | undefined;
    const listenerSpy = jest.spyOn(AppState, "addEventListener").mockImplementation((_type, listener) => {
      appStateListener = listener;
      return { remove: jest.fn() };
    });
    const screen = render(
      <App
        fetchImpl={successfulFetch() as never}
        socketFactory={() => new QuietSocket() as never}
        store={store(jest.fn().mockResolvedValue("persistido"))}
      />,
    );
    await screen.findByText("Depositar");
    act(() => appStateListener?.("background"));
    expect(screen.getByTestId("privacy-overlay")).toBeTruthy();
    act(() => appStateListener?.("active"));
    expect(screen.queryByTestId("privacy-overlay")).toBeNull();
    screen.unmount();
    listenerSpy.mockRestore();
  });

  test("AT-10-01-07 por paridad avisa que la sesión expiró al volver al login", async () => {
    const fetchImpl = jest.fn().mockResolvedValue({
      ok: false,
      status: 401,
      json: jest.fn().mockResolvedValue({
        error: { code: "UNAUTHENTICATED", message: "Credencial inválida." },
      }),
    });
    const localStore = store(jest.fn().mockResolvedValue("expirado"));
    const screen = render(
      <App
        fetchImpl={fetchImpl as never}
        socketFactory={() => new QuietSocket() as never}
        store={localStore}
      />,
    );

    expect(await screen.findByText("Tu sesión expiró, ingresá nuevamente.")).toBeTruthy();
    expect(localStore.clearToken).toHaveBeenCalledTimes(1);
    expect(screen.getByText("Ingresá a tu cuenta")).toBeTruthy();
  });

  test("AT-11-01-06 el logout voluntario vuelve al login sin aviso de expiración", async () => {
    const localStore = store(jest.fn().mockResolvedValue("vigente"));
    const screen = render(
      <App
        fetchImpl={successfulFetch() as never}
        socketFactory={() => new QuietSocket() as never}
        store={localStore}
      />,
    );
    await screen.findByText("Depositar");
    fireEvent.press(screen.getByRole("button", { name: "Cerrar sesión" }));

    expect(await screen.findByText("Ingresá a tu cuenta")).toBeTruthy();
    expect(screen.queryByText("Tu sesión expiró, ingresá nuevamente.")).toBeNull();
    expect(localStore.clearToken).toHaveBeenCalledTimes(1);
  });
});

