1→import { PrivateSocket } from "./privateSocket";

class FakeSocket {
  readyState = 0;
  sent: string[] = [];
  onopen: (() => void) | null = null;
  onmessage: ((event: { data: string }) => void) | null = null;
  onclose: ((event: { code: number }) => void) | null = null;
  onerror: (() => void) | null = null;
10→  send(value: string) { this.sent.push(value); }
  close(code = 1000) { this.readyState = 3; this.onclose?.({ code }); }
  open() { this.readyState = 1; this.onopen?.(); }
  message(data: unknown) { this.onmessage?.({ data: JSON.stringify(data) }); }
  disconnect(code = 1006) { this.readyState = 3; this.onclose?.({ code }); }
}

describe("WebSocket privado", () => {
  test("AT-11-01-12 autentica como primer mensaje, responde heartbeat y no pone token en URL", () => {
    const fake = new FakeSocket();
20→    let openedUrl = "";
    const socket = new PrivateSocket({
      baseUrl: "https://api.example.test/",
      token: "token-privado",
      onUnauthenticated: jest.fn(),
      socketFactory: ((url: string) => { openedUrl = url; return fake; }) as never,
    });
    socket.start();
    fake.open();
    expect(openedUrl).toBe("wss://api.example.test/api/v1/ws");
30→    expect(openedUrl).not.toContain("token-privado");
    expect(fake.sent).toEqual([JSON.stringify({ type: "auth", token: "token-privado" })]);
    fake.message({ type: "ping" });
    expect(fake.sent[1]).toBe(JSON.stringify({ type: "pong" }));
  });

  test("AT-11-01-12/14 comparte el callback de UNAUTHENTICATED una sola vez", () => {
    const fake = new FakeSocket();
    const unauthenticated = jest.fn();
    const socket = new PrivateSocket({
40→      baseUrl: "http://localhost:3000",
      token: "token",
      onUnauthenticated: unauthenticated,
      socketFactory: (() => fake) as never,
    });
    socket.start();
    fake.open();
    fake.message({ error: { code: "UNAUTHENTICATED" } });
    fake.disconnect(4001);
    expect(unauthenticated).toHaveBeenCalledTimes(1);
50→    expect(unauthenticated).toHaveBeenCalledWith("token");
  });

  test("RG-10 reconecta con backoff 1s, factor 2 y jitter acotado", () => {
    const firstSocket = new FakeSocket();
    const sockets = [firstSocket, new FakeSocket()];
    const delays: number[] = [];
    const callbacks: Array<() => void> = [];
    const socket = new PrivateSocket({
      baseUrl: "http://localhost:3000",
60→      token: "token",
      onUnauthenticated: jest.fn(),
      random: () => 0.5,
      socketFactory: (() => sockets.shift()!) as never,
      schedule: ((callback: () => void, delay: number) => { callbacks.push(callback); delays.push(delay); return 1; }) as never,
      cancelSchedule: jest.fn(),
    });
    socket.start();
    firstSocket.disconnect();
    expect(delays).toEqual([1000]);
70→    callbacks[0]!();
  });

  test("RG-10 limita a 30s también después de aplicar jitter", () => {
    const fake = new FakeSocket();
    const delays: number[] = [];
    const socket = new PrivateSocket({
      baseUrl: "http://localhost:3000",
      token: "token",
      onUnauthenticated: jest.fn(),
80→      random: () => 1,
      socketFactory: (() => fake) as never,
      schedule: ((_callback: () => void, delay: number) => { delays.push(delay); return 1; }) as never,
      cancelSchedule: jest.fn(),
    });
    (socket as unknown as { attempt: number }).attempt = 10;
    socket.start();
    (socket as unknown as { attempt: number }).attempt = 10;
    fake.disconnect();
    expect(delays).toEqual([30_000]);
90→  });
});

